class Solution {
public:
    int maxArea(vector<int>& height) {
        int n = height.size();
        int maxArea = 0;
        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                int h = min(height[i], height[j]);
                int area = h * (j - i);
                maxArea = max(maxArea, area);
            }
        }
        return maxArea;
    }
};

