from typing import List
class Solution:
    def maxArea(self, height: List[int]) -> int:
        n = len(height)
        max_area = 0
        for i in range(n):
            for j in range(i + 1, n):
                h = height[i] if height[i] < height[j] else height[j]
                area = h * (j - i)
                if area > max_area:
                    max_area = area
        return max_area

